L["GUIDE_LOCKED_ITEMS_TITLE"] = "Locked Items"
L["GUIDE_LOCKED_ITEMS_DESC"] = [[Protect items from being sold, deleted, or disenchanted.
|cff00ccccCtrl + Right-Click|r an item to lock/unlock it.
Locked items cannot be |cffff0000sold|r at vendors, |cffff0000deleted|r, or |cffff0000disenchanted|r.
Equipment set items are automatically protected.
A lock icon appears on the bottom-right corner.]]

