Gli oggetti bloccati non possono essere |cffff0000venduti|r, |cffff0000eliminati|r o |cffff0000disincantati|r.
Gli oggetti dei set equipaggiamento sono protetti automaticamente.
Un'icona lucchetto appare nell'angolo in basso a destra.]]

L["GUIDE_PIN_SLOT_TITLE"] = "Fissa slot"
L["GUIDE_PIN_SLOT_RETAIL_NOTE"] = "Attiva ordinamento GudaBags"
L["GUIDE_PIN_SLOT_DESC"] = [[Fissa uno slot borsa per proteggerlo dall'ordinamento.
|cff00ccccAlt + Clic destro|r per fissare/sbloccare.
Gli slot fissati vengono |cff00ccccignora|r durante l'ordinamento.
La fissatura resta sullo slot, non sull'oggetto.
Un'icona puntina appare in basso a sinistra.]]

